// GreetingController.java
@RestController
class GreetingController {
    private final String greeting;
    private final int retries;

    GreetingController(@Value("${app.greeting}") String greeting,
                       @Value("${app.retries:3}") int retries) {   // default 3
        this.greeting = greeting;
        this.retries = retries;
    }

    @GetMapping("/greet")
    String greet() { return greeting + " (retries=" + retries + ")"; }
}
// GET :8081/greet -> Hello from shop (retries=3)
// SERVER_PORT=9000 java -jar shop.jar   -> now listens on 9000

record Book(long id, String title, String author) {}

@RestController
@RequestMapping("/api/books")
class BookController {
    private final Map<Long, Book> books = Map.of(
        1L, new Book(1, "Dune", "Herbert"),
        2L, new Book(2, "Emma", "Austen"));

    @GetMapping
    List<Book> list(@RequestParam(defaultValue = "") String author) {
        return books.values().stream()
            .filter(b -> author.isEmpty() || b.author().equalsIgnoreCase(author))
            .toList();
    }

    @GetMapping("/{id}")
    ResponseEntity<Book> get(@PathVariable long id) {
        Book b = books.get(id);
        return b == null ? ResponseEntity.notFound().build() : ResponseEntity.ok(b);
    }
}
// GET /api/books?author=austen -> [{"id":2,"title":"Emma","author":"Austen"}]
// GET /api/books/7 -> 404    GET /api/books/abc -> 400

record CreateTodo(String title) {}
record Todo(long id, String title, boolean done) {}
@RestController
@RequestMapping("/api/todos")
class TodoController {
    private final Map<Long, Todo> store = new ConcurrentHashMap<>();
    private final AtomicLong ids = new AtomicLong();
    @PostMapping
    ResponseEntity<Todo> create(@RequestBody CreateTodo req) {
        Todo t = new Todo(ids.incrementAndGet(), req.title(), false);
        store.put(t.id(), t);
        URI location = ServletUriComponentsBuilder.fromCurrentRequest()
            .path("/{id}").buildAndExpand(t.id()).toUri();
        return ResponseEntity.created(location).body(t);       // 201 + Location
    }
    @DeleteMapping("/{id}")
    ResponseEntity<Void> delete(@PathVariable long id) {
        return store.remove(id) != null
            ? ResponseEntity.noContent().build()                // 204
            : ResponseEntity.notFound().build();                // 404
    }
}
// curl -i -X POST localhost:8080/api/todos -H 'Content-Type: application/json' \
