@Entity
class Book {
    @Id @GeneratedValue Long id;
    String title;
    String author;
    LocalDate published;
    protected Book() {}                            // required by JPA
    Book(String title, String author, LocalDate published) {
        this.title = title; this.author = author; this.published = published;
    }
}
interface BookRepository extends JpaRepository<Book, Long> {
    List<Book> findByAuthorIgnoreCase(String author);
    List<Book> findByTitleContainingIgnoreCase(String fragment);
    long countByPublishedAfter(LocalDate date);
    @Query("select b from Book b where b.published < :date order by b.published")
    List<Book> classicsBefore(@Param("date") LocalDate date);
}
@Service
class Catalog {
    private final BookRepository repo;
    Catalog(BookRepository repo) { this.repo = repo; }
    Book add(String t, String a, LocalDate d) { return repo.save(new Book(t, a, d)); }
    Optional<Book> find(long id) { return repo.findById(id); }
}

