@Service
class TransferService {
    private final AccountRepository accounts;
    private final AuditService audit;
    TransferService(AccountRepository accounts, AuditService audit) {
        this.accounts = accounts; this.audit = audit;
    }

    @Transactional
    public void transfer(long from, long to, BigDecimal amount) {
        Account a = accounts.findById(from).orElseThrow();
        Account b = accounts.findById(to).orElseThrow();
        audit.record("transfer " + amount);      // REQUIRES_NEW: survives rollback
        a.withdraw(amount);                      // dirty checking: no save() needed
        b.deposit(amount);
        if (a.getBalance().signum() < 0)
            throw new IllegalStateException("insufficient funds");  // rolls back both
    }
}

@Service
class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void record(String event) { /* insert audit row */ }
}

record User(long id, String name) {}

@Service
class UserClient {
    private final RestClient client;

    UserClient(RestClient.Builder builder) {          // auto-configured by Boot
        this.client = builder.baseUrl("https://jsonplaceholder.typicode.com").build();
    }

    User find(long id) {
        return client.get().uri("/users/{id}", id)
            .retrieve()
            .onStatus(HttpStatusCode::is4xxClientError, (req, res) -> {
                throw new IllegalArgumentException("no user " + id);
            })
            .body(User.class);
    }

    List<User> all() {
        return client.get().uri("/users").retrieve()
            .body(new ParameterizedTypeReference<List<User>>() {});
    }
}
// find(1) -> User[id=1, name=Leanne Graham]

