// A simplified version of what Boot ships, showing the patterns
@AutoConfiguration
@ConditionalOnClass(ObjectMapper.class)
public class SimpleJacksonAutoConfiguration {
    @Bean
    @ConditionalOnMissingBean                    // backs off if you define one
    ObjectMapper objectMapper(ObjectProvider<MapperCustomizer> customizers) {
        ObjectMapper mapper = new ObjectMapper().findAndRegisterModules();
        customizers.orderedStream().forEach(c -> c.customize(mapper));
        return mapper;
    }
}
interface MapperCustomizer { void customize(ObjectMapper mapper); }
// Your app: tweak instead of replace
@Bean
MapperCustomizer indent() {
    return m -> m.enable(SerializationFeature.INDENT_OUTPUT);
}
