@Entity
class Order {
    @Id @GeneratedValue Long id;
    @ManyToOne(fetch = FetchType.LAZY) Customer customer;   // default would be EAGER
    BigDecimal total;
}

record OrderSummary(Long id, String customerName, BigDecimal total) {}

interface OrderRepository extends JpaRepository<Order, Long> {
    // 1 query instead of 1 + N
    @EntityGraph(attributePaths = "customer")
    List<Order> findByTotalGreaterThan(BigDecimal min);

    // DTO projection: only the needed columns, no managed entities
    @Query("select new com.example.OrderSummary(o.id, c.name, o.total) " +
           "from Order o join o.customer c where o.total > :min")
    Page<OrderSummary> summaries(@Param("min") BigDecimal min, Pageable page);
}

