@Aspect
@Component
class TimingAspect {
    @Around("@annotation(com.example.Timed)")
    Object time(ProceedingJoinPoint pjp) throws Throwable {
        long start = System.nanoTime();
        try { return pjp.proceed(); }
        finally {
            System.out.printf("%s took %d us%n", pjp.getSignature().toShortString(),
                (System.nanoTime() - start) / 1000);
        }
    }
}

@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface Timed {}

@Service
class ReportService {
    @Timed public String build() { return "report " + this.helper(); } // timed
    @Timed public String helper() { return "data"; }  // NOT timed when called via this
    @PostConstruct void init() { System.out.println("ready: " + getClass().getSimpleName()); }
}
// ready: ReportService           (init runs on the target, before proxying)
