    private final ApplicationContextRunner runner = new ApplicationContextRunner()
        .withConfiguration(AutoConfigurations.of(AuditAutoConfiguration.class));

    @Test void createsClient() { runner.run(ctx -> assertThat(ctx).hasSingleBean(AuditClient.class)); }
    @Test void canBeDisabled() { runner.withPropertyValues("acme.audit.enabled=false")
        .run(ctx -> assertThat(ctx).doesNotHaveBean(AuditClient.class)); }
}

// Hints for things AOT can't infer, e.g. reflective access to a library class
class ReportHints implements RuntimeHintsRegistrar {
    @Override
    public void registerHints(RuntimeHints hints, ClassLoader cl) {
        hints.reflection().registerType(ReportRow.class,
            MemberCategory.INVOKE_PUBLIC_CONSTRUCTORS, MemberCategory.INVOKE_PUBLIC_METHODS);
        hints.resources().registerPattern("templates/report/*.txt");
    }
}

@Configuration
@ImportRuntimeHints(ReportHints.class)
class ReportConfig {}

